FILE: app/src/release.ts
```ts
import { getAnimationGroups, stopAnimation } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

function resolvePath(obj: object, path: string): object | undefined {
    const parts = path.split(".");
    let current: any = obj;
    for (const part of parts) {
        if (current == null) return undefined;
        current = current[part];
    }
    return current;
}

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const segments = path.split(".");
    const lastSegment = segments[segments.length - 1];
    const parentPath = segments.slice(0, -1).join(".");
    const parent = parentPath ? resolvePath(target, parentPath) : target;

    if (parent == null) return;

    const groups = getAnimationGroups(manager);
    for (const group of groups) {
        const targeted = group.targetedAnimations;
        for (let i = 0; i < targeted.length; i++) {
            const entry = targeted[i];
            if (entry.target === parent && entry.path === lastSegment) {
                stopAnimation(group);
                break;
            }
        }
    }
}
```

I wrote `src/release.ts` which resolves the parent object for the given dotted path, then iterates every group on the manager and calls `stopAnimation` on any whose `targetedAnimations` contain an entry whose `target` is that parent object and whose `path` is the final segment. Using `stopAnimation` (rather than `pauseAnimation`) guarantees the group takes no part in writing even under `enablePropertyAnimationBlending` (per note 32), so the property is fully released regardless of whether blending is active. I was not sure whether you'd prefer `pauseAnimation` (which preserves `currentTime` for later resumption) over `stopAnimation` (which resets to the start), but since the spec says "stops" and blending makes pause insufficient on its own, I went with stop.
